This is a miscompilation bug in InstCombine.
Issue title: [RISC-V] Miscompile using rv64gcv
Detailed information:
Source:
define i1 @pr126974(i8 %x) {
entry:
  %cond = icmp sgt i8 %x, -2
  br i1 %cond, label %if.then, label %if.else

if.then:                                          ; preds = %entry
  %umax = call i8 @llvm.umax.i8(i8 %x, i8 -46)
  %cmp = icmp samesign ult i8 %umax, -32
  ret i1 %cmp

if.else:                                          ; preds = %entry
  ret i1 false
}

; Function Attrs: nocallback nosync nounwind speculatable willreturn memory(none)
declare i8 @llvm.umax.i8(i8, i8) #0

attributes #0 = { nocallback nosync nounwind speculatable willreturn memory(none) }

Target:
; ModuleID = '<stdin>'
source_filename = "<stdin>"

define i1 @pr126974(i8 %x) {
entry:
  %cond = icmp sgt i8 %x, -2
  br i1 %cond, label %if.then, label %if.else

if.then:                                          ; preds = %entry
  ret i1 false

if.else:                                          ; preds = %entry
  ret i1 false
}

; Function Attrs: nocallback nosync nounwind speculatable willreturn memory(none)
declare i8 @llvm.umax.i8(i8, i8) #0

attributes #0 = { nocallback nosync nounwind speculatable willreturn memory(none) }

Transformation doesn't verify!

ERROR: Value mismatch

Example:
i8 %x = #x00 (0)

Source:
i1 %cond = #x1 (1)
  >> Jump to %if.then
i8 %umax = #xd2 (210, -46)
i1 %cmp = #x1 (1)

Target:
i1 %cond = #x1 (1)
  >> Jump to %if.then
Source value: #x1 (1)
Target value: #x0 (0)

Summary:
  0 correct transformations
  1 incorrect transformations
  0 failed-to-prove transformations
  0 Alive2 errors

